      if (!!(s && (s as any).__v_isRef === true)) {
        return s.value
      } else if (isReactive(s)) {
        return reactiveGetter(s)
      } else if (isFunction(s)) {
        try {
          return s()
        } catch (err) {
          handleError(err, instance, ErrorCodes.WATCH_GETTER)
        }
      } else {
        __DEV__ && warnInvalidSource(s)
      }
    })
} else if (isFunction(source)) {
  if (cb) {
    // getter with cb
    getter = () => {
      try {
        return source()
      } catch (err) {
        handleError(err, instance, ErrorCodes.WATCH_GETTER)
      }
    }
  } else {
    // no cb -> simple effect
    getter = () => {
      if (cleanup) {
        cleanup()
      }
      try {
        const res = (source as WatchEffect)(onCleanup)
        if (res && isPromise(res)) {
          res.catch(err => {
            handleError(err, instance, ErrorCodes.WATCH_CALLBACK)
          })
        }
        return res
      } catch (err) {
        handleError(err, instance, ErrorCodes.WATCH_CALLBACK)
      }
    }
